mapper.select:
SELECT yg.id, yg.yard_task_id, yg.warehouse_id, yg.dock_id, yg.dock_code,
       yg.robot_task_id, yg.robot_status, yg.task_type, yg.progress,
       yg.start_time, yg.finish_time, yg.remark, yg.create_time
FROM yms_yardgo_task yg
WHERE yg.deleted = 0

      AND yg.warehouse_id = #{bo.warehouseId}


      AND yg.yard_task_id = #{bo.yardTaskId}


      AND yg.dock_id = #{bo.dockId}


      AND yg.robot_status = #{bo.robotStatus}


      AND yg.task_type = #{bo.taskType}

ORDER BY yg.create_time DESC
